# owner: platform
"""Seat students in rows, sorted by last name."""

from typing import Iterable, List

from rosterkit.errors import ProjectError
from rosterkit.models import Student

def sort_key(student: Student):
    return (
        student.last_name.lower(),
        student.first_name.lower(),
        student.student_id
    )

def check_inputs(students: List[Student], per_row: int):
    if per_row <= 0:
        raise ValueError("seats per row must be positive")
    if not students:
        raise ProjectError("no students to seat")

def chunk(items: List[Student], size: int):
    for start in range(0, len(items), size):
        yield items[start:start + size]

def format_row(number: int, row: List[Student]) -> str:
    names = " | ".join(s.display_name for s in row)
    return f"Row {number}: {names}"

def seat_rows(
    students: Iterable[Student], per_row: int
) -> List[str]:
    """One line per row: ``Row 1: Dunmere, Piet | ...``."""
    ordered = sorted(students, key=sort_key)
    check_inputs(ordered, per_row)
    rows = chunk(ordered, per_row)
    return [format_row(n, r) for n, r in enumerate(rows, 1)]

