# owner: platform
import unittest

from rosterkit.errors import ProjectError
from rosterkit.models import Student
from rosterkit.seating import seat_rows

def make(last: str, first: str, number: int) -> Student:
    return Student(str(number), last, first, "A")

def sample() -> list:
    return [
        make("Halloway", "Juno", 1),
        make("Dunmere", "Piet", 2),
        make("Ankrum", "Sol", 3)
    ]

class SeatRowsTests(unittest.TestCase):
    def test_sorts_and_fills_rows(self):
        self.assertEqual(
            seat_rows(sample(), 2),
            [
                "Row 1: Ankrum, Sol | Dunmere, Piet",
                "Row 2: Halloway, Juno"
            ]
        )

    def test_single_row_when_seats_exceed_students(self):
        lines = seat_rows(sample(), 10)
        self.assertEqual(len(lines), 1)

    def test_ties_break_on_first_name(self):
        zed = make("Lee", "Zed", 1)
        amy = make("Lee", "Amy", 2)
        lines = seat_rows([zed, amy], 2)
        self.assertEqual(lines, [
            "Row 1: Lee, Amy | Lee, Zed"
        ])

    def test_zero_seats_raises(self):
        with self.assertRaises(ValueError):
            seat_rows(sample(), 0)

    def test_negative_seats_raises(self):
        with self.assertRaises(ValueError):
            seat_rows(sample(), -3)

    def test_no_students_raises(self):
        with self.assertRaises(ProjectError):
            seat_rows([], 3)
